/* Catálogo docente inicial. Los ejemplos hipotéticos están separados de estudios y casos documentados. */
window.CONCEPTS = [
 {id:'confirmacion',kind:'sesgo',name:'Sesgo de confirmación',category:'Selección y evaluación de evidencia',short:'Buscamos o interpretamos información de forma que favorezca una creencia previa.',description:'Al evaluar una idea, podemos dar más peso a la evidencia que la apoya y menos a la que la cuestiona. No significa que toda búsqueda de información favorable sea sesgada: importa si buscamos pruebas de forma asimétrica.',signals:['Solo se enumeran fuentes o ejemplos favorables.','Una objeción se descarta sin aplicar el mismo estándar que a la evidencia favorable.','La conclusión parece fijada antes de comparar las pruebas.'],why:'La búsqueda selectiva puede ahorrar esfuerzo y proteger una interpretación conocida; también puede hacer que la evidencia parezca más concluyente de lo que es.',counter:'Antes de buscar, escribe qué evidencia te haría cambiar de opinión. Busca deliberadamente una explicación rival y evalúa ambas con los mismos criterios.',examples:['Alguien lee únicamente reseñas positivas antes de comprar y luego considera que el producto está probado como el mejor.','Un equipo investiga solo incidentes compatibles con su hipótesis y no busca casos que podrían refutarla.','Una persona recuerda los aciertos de una predicción y olvida los fallos.'],cases:[{title:'Asimilación sesgada de evidencia sobre pena de muerte',text:'Participantes con posturas previas opuestas evaluaron evidencia mixta y tendieron a asimilarla de manera favorable a su postura.',source:'Lord, Ross & Lepper (1979)',url:'https://doi.org/10.1037/0022-3514.37.11.2098'},{title:'Estrategia de considerar lo contrario',text:'En dos experimentos, inducir a considerar posibilidades opuestas redujo ciertas formas de asimilación sesgada y de prueba de hipótesis.',source:'Lord, Lepper & Preston (1984)',url:'https://pubmed.ncbi.nlm.nih.gov/6527215/'},{title:'Revisión de sesgos en verificación de datos',text:'Una revisión identifica el sesgo de confirmación entre los riesgos que pueden afectar la evaluación de afirmaciones.',source:'Cognitive Biases in Fact-Checking (2024)',url:'https://doi.org/10.1016/j.ipm.2024.103672'}],sources:[['Lord, Ross & Lepper (1979)','https://doi.org/10.1037/0022-3514.37.11.2098'],['Lord, Lepper & Preston (1984)','https://pubmed.ncbi.nlm.nih.gov/6527215/'],['Review: Cognitive Biases in Fact-Checking (2024)','https://doi.org/10.1016/j.ipm.2024.103672']],videos:[['Confirmation Bias — University of Texas','https://www.youtube.com/watch?v=7zoWTb3KP-k',0,'Introducción y ejemplos'],['Every Cognitive Bias Explained — Confirmation Bias','https://www.youtube.com/watch?v=m3Nfnp4NAdg',118,'Segmento 01:58'],['12 Cognitive Biases Explained — Confirmation Bias','https://www.youtube.com/watch?v=wEwGBIr_RIw',230,'Segmento 03:50'] ]},
 {id:'disponibilidad',kind:'sesgo',name:'Heurística de disponibilidad',category:'Selección y evaluación de evidencia',short:'Estimamos qué tan frecuente o probable es algo según lo fácil que recordamos ejemplos.',description:'La facilidad con que vienen casos a la mente puede influir en los juicios de frecuencia o riesgo. Noticias recientes, vívidas o repetidas pueden ser más memorables que los datos de base.',signals:['Se infiere frecuencia a partir de uno o pocos casos recordados.','Un ejemplo llamativo desplaza tasas o estadísticas.','La exposición reciente se toma como señal de que algo es común.'],why:'La memoria accesible ofrece una respuesta rápida cuando estimar una frecuencia real requiere datos o esfuerzo.',counter:'Busca tasas de base y series representativas. Pregunta cuántos casos hay en el total, qué periodo se cubre y qué casos no se recuerdan fácilmente.',examples:['Tras ver varias noticias de accidentes, alguien concluye que volar es más peligroso que conducir sin comparar tasas.','Un gerente estima una conducta por las anécdotas recientes de su equipo.','Un riesgo raro parece común después de una historia muy gráfica.'],cases:[{title:'Juicios de frecuencia y disponibilidad',text:'Experimentos clásicos mostraron que la facilidad para recordar ejemplos puede influir en estimaciones de frecuencia.',source:'Tversky & Kahneman (1973)',url:'https://doi.org/10.1016/0010-0285(73)90033-9'},{title:'Juicio bajo incertidumbre',text:'La disponibilidad fue descrita como una heurística de juicio que puede producir estimaciones sistemáticamente desviadas.',source:'Tversky & Kahneman (1974)',url:'https://doi.org/10.1126/science.185.4157.1124'},{title:'Sesgos en evaluación de información',text:'La revisión de sesgos relacionados con fact-checking incluye la disponibilidad como riesgo relevante de juicio.',source:'Cognitive Biases in Fact-Checking (2024)',url:'https://doi.org/10.1016/j.ipm.2024.103672'}],sources:[['Tversky & Kahneman (1973)','https://doi.org/10.1016/0010-0285(73)90033-9'],['Tversky & Kahneman (1974)','https://doi.org/10.1126/science.185.4157.1124'],['Review: Cognitive Biases in Fact-Checking (2024)','https://doi.org/10.1016/j.ipm.2024.103672']],videos:[['Introduction to Cognitive Bias — Crash Course','https://www.youtube.com/watch?v=m3Nfnp4NAdg',23,'Segmento Availability Heuristic, 00:23'],['12 Cognitive Biases Explained — Practical Psychology','https://www.youtube.com/watch?v=wEwGBIr_RIw',82,'Segmento Availability Bias, 01:22'],['Hidden Traps in Decision Making','https://www.youtube.com/watch?v=gkIkqJMdv2o',0,'Ejemplos de trampas de decisión']]},
 {id:'anclaje',kind:'sesgo',name:'Anclaje',category:'Estimación y decisión',short:'Una cifra o dato inicial influye demasiado en una estimación posterior.',description:'Al juzgar una cantidad, una referencia inicial puede sesgar ajustes posteriores, incluso cuando esa referencia es arbitraria o poco informativa.',signals:['La cifra inicial se repite como base sin justificarla.','Los ajustes quedan cerca de una referencia irrelevante.','Dos estimaciones difieren mucho por el primer número que vieron.'],why:'Las personas suelen ajustar desde un punto de partida y pueden detenerse antes de compensar suficientemente su influencia.',counter:'Haz una estimación independiente antes de ver referencias; compara con varias fuentes y documenta el método de ajuste.',examples:['Un precio tachado hace que el precio actual parezca una ganga sin comparar el mercado.','Una oferta inicial condiciona el rango de negociación.','Un presupuesto preliminar se mantiene pese a nueva información.'],cases:[{title:'Anclaje y ajuste insuficiente',text:'Los estudios de Tversky y Kahneman demostraron que valores iniciales arbitrarios pueden afectar estimaciones numéricas.',source:'Tversky & Kahneman (1974)',url:'https://doi.org/10.1126/science.185.4157.1124'},{title:'Efecto de anclaje en negociaciones',text:'Una revisión y metaanálisis evalúa los efectos de las ofertas iniciales en negociación.',source:'Orr & Guthrie (2006)',url:'https://doi.org/10.1111/j.1740-8784.2006.00084.x'},{title:'Sesgos en fact-checking',text:'Anclaje figura entre los sesgos examinados para la evaluación de afirmaciones.',source:'Cognitive Biases in Fact-Checking (2024)',url:'https://doi.org/10.1016/j.ipm.2024.103672'}],sources:[['Tversky & Kahneman (1974)','https://doi.org/10.1126/science.185.4157.1124'],['Orr & Guthrie (2006)','https://doi.org/10.1111/j.1740-8784.2006.00084.x'],['Cognitive Biases in Fact-Checking (2024)','https://doi.org/10.1016/j.ipm.2024.103672']],videos:[['12 Cognitive Biases Explained','https://www.youtube.com/watch?v=m3Nfnp4NAdg',2,'Segmento Anchoring Bias, 00:02'],['Introduction to Cognitive Bias — Crash Course','https://www.youtube.com/watch?v=d2r7Bk1NlgU',0,'Introducción a sesgos cognitivos'],['Hidden Traps in Decision Making','https://www.youtube.com/watch?v=m3Nfnp4NAdg',224,'Segmento Framing Effect, 03:44']]},
 {id:'encuadre',kind:'sesgo',name:'Efecto de encuadre',category:'Estimación y decisión',short:'La manera de presentar opciones cambia la preferencia aunque la información esencial sea equivalente.',description:'La descripción en términos de ganancias o pérdidas, por ejemplo, puede modificar cómo se evalúa una opción. El marco no siempre cambia la decisión; el efecto depende del contexto y la formulación.',signals:['Se compara “vidas salvadas” con “vidas perdidas” como si fueran opciones distintas.','La presentación emocional reemplaza una comparación común.','Se omite que dos descripciones comunican el mismo resultado.'],why:'La presentación puede cambiar qué aspecto de una opción destaca y cómo se percibe el riesgo.',counter:'Reescribe todas las opciones en el mismo formato neutral y compara resultados, probabilidades y supuestos.',examples:['“90 % libre de grasa” frente a “10 % de grasa”.','Una política se describe por beneficios potenciales o por pérdidas evitables.','Una tasa se comunica como frecuencia absoluta en vez de porcentaje.'],cases:[{title:'El problema de la enfermedad asiática',text:'El experimento clásico mostró cambios de preferencia al describir opciones equivalentes en términos de vidas salvadas o perdidas.',source:'Tversky & Kahneman (1981)',url:'https://doi.org/10.1126/science.7455683'},{title:'Marco de ganancia/pérdida y decisión',text:'La teoría prospectiva formalizó cómo el encuadre de resultados puede influir en elecciones bajo riesgo.',source:'Kahneman & Tversky (1979)',url:'https://doi.org/10.2307/1914185'},{title:'Encuadre y juicio de riesgo',text:'La investigación posterior documenta condiciones y límites contextuales de los efectos de encuadre.',source:'Levin, Schneider & Gaeth (1998)',url:'https://doi.org/10.1037/0033-2909.123.2.149'}],sources:[['Tversky & Kahneman (1981)','https://doi.org/10.1126/science.7455683'],['Kahneman & Tversky (1979)','https://doi.org/10.2307/1914185'],['Levin, Schneider & Gaeth (1998)','https://doi.org/10.1037/0033-2909.123.2.149']],videos:[['Every Psychological Traps in 20 Minutes','https://www.youtube.com/watch?v=DdcK-9eOtOc',508,'Segmento The Sunk Cost Fallacy, 08:28'],['Introduction to Cognitive Bias — Crash Course','https://www.youtube.com/watch?v=d2r7Bk1NlgU',0,'Introducción y contexto'],['Hidden Traps in Decision Making','https://www.youtube.com/watch?v=gkIkqJMdv2o',0,'Ejemplos cotidianos']]},
 {id:'costo-hundido',kind:'sesgo',name:'Costo hundido',category:'Estimación y decisión',short:'Continuamos invirtiendo por lo ya gastado, aunque esos costos no se recuperen.',description:'Tiempo, dinero o esfuerzo pasados pueden pesar en una decisión que debería considerar principalmente los costos y beneficios futuros. No todo seguimiento de una inversión previa es irracional: puede haber información nueva relevante.',signals:['“Ya invertimos demasiado para abandonar” sin valorar perspectivas futuras.','El costo pasado se usa como razón principal para continuar.','Se ignora una alternativa mejor porque ya se empezó.'],why:'Abandonar una inversión puede sentirse como admitir una pérdida; además, la persistencia puede confundirse con compromiso o coherencia.',counter:'Imagina que hoy empiezas desde cero. Compara los resultados esperados de continuar frente a cambiar, sin contar costos irrecuperables.',examples:['Seguir viendo una película que no gusta porque ya se pagó la entrada.','Mantener un proyecto fallido por el presupuesto ya gastado.','Continuar una reparación costosa solo porque se pagaron varias etapas.'],cases:[{title:'Escalada de compromiso',text:'La investigación estudia la persistencia en cursos de acción tras resultados negativos y los factores que la sostienen.',source:'Staw (1976)',url:'https://doi.org/10.2307/255362'},{title:'Costo hundido en decisiones',text:'Arkes y Blumer analizaron experimentalmente cómo costos pasados pueden aumentar la continuación de una inversión.',source:'Arkes & Blumer (1985)',url:'https://doi.org/10.1016/0749-5978(85)90049-4'},{title:'Persistencia ante evidencia negativa',text:'Una revisión de escalada de compromiso examina resultados, mecanismos y condiciones.',source:'Sleesman et al. (2012)',url:'https://doi.org/10.5465/amr.2010.0358'}],sources:[['Staw (1976)','https://doi.org/10.2307/255362'],['Arkes & Blumer (1985)','https://doi.org/10.1016/0749-5978(85)90049-4'],['Sleesman et al. (2012)','https://doi.org/10.5465/amr.2010.0358']],videos:[['12 Cognitive Biases Explained','https://www.youtube.com/watch?v=m3Nfnp4NAdg',317,'Segmento Illusory Truth Effect, 05:17'],['Introduction to Cognitive Bias — Crash Course','https://www.youtube.com/watch?v=d2r7Bk1NlgU',0,'Introducción'],['Hidden Traps in Decision Making','https://www.youtube.com/watch?v=gkIkqJMdv2o',0,'Decisiones y sesgos']]},
 {id:'halo',kind:'sesgo',name:'Efecto halo',category:'Juicio social',short:'Una impresión destacada influye en la evaluación de otras características no relacionadas.',description:'Una característica positiva o negativa puede colorear juicios sobre otros rasgos. Es una tendencia de evaluación, no una prueba de que una impresión sea siempre equivocada.',signals:['Una cualidad se usa para inferir otras sin evidencia.','El prestigio o apariencia reemplaza evaluar el desempeño específico.','La valoración global no distingue dimensiones.'],why:'Las impresiones generales pueden organizar y simplificar juicios sobre personas, marcas o instituciones.',counter:'Evalúa cada dimensión por separado con criterios observables. Pide evidencia independiente para cada atributo.',examples:['Una persona elocuente se considera automáticamente experta.','Una marca reconocida se asume superior en todas sus características.','Una buena primera impresión pesa más que evidencia posterior.'],cases:[{title:'Juicios de personalidad y efecto halo',text:'Thorndike describió cómo evaluaciones de una característica pueden correlacionarse con juicios sobre otras en valoraciones de personal.',source:'Thorndike (1920)',url:'https://doi.org/10.1037/h0071663'},{title:'Efecto halo en evaluación psicológica',text:'Nisbett y Wilson estudiaron cómo una impresión general afecta evaluaciones de atributos particulares.',source:'Nisbett & Wilson (1977)',url:'https://doi.org/10.1016/0022-1031(77)90020-6'},{title:'Síntesis sobre halo',text:'La investigación moderna revisa procesos y aplicaciones del efecto halo en juicios y decisiones.',source:'Forgas & Laham (2017)',url:'https://doi.org/10.1002/9781118926485.ch10'}],sources:[['Thorndike (1920)','https://doi.org/10.1037/h0071663'],['Nisbett & Wilson (1977)','https://doi.org/10.1016/0022-1031(77)90020-6'],['Forgas & Laham (2017)','https://doi.org/10.1002/9781118926485.ch10']],videos:[['Fundamental Attribution Error — McCombs School of Business','https://www.youtube.com/watch?v=Y8IcYSrcaaA',0,'Ejemplo de juicio social'],['12 Cognitive Biases Explained','https://www.youtube.com/watch?v=m3Nfnp4NAdg',263,'Segmento Halo Effect, 04:23'],['Introduction to Cognitive Bias — Crash Course','https://www.youtube.com/watch?v=d2r7Bk1NlgU',0,'Introducción']]},
 {id:'atribucion',kind:'sesgo',name:'Error fundamental de atribución',category:'Juicio social',short:'Sobreestimamos rasgos personales y subestimamos la situación al explicar la conducta ajena.',description:'Al explicar las acciones de otras personas, solemos dar demasiado peso a disposiciones y demasiado poco a circunstancias. La magnitud de este patrón varía según la cultura y el contexto.',signals:['Se explica una acción ajena solo por su carácter.','Se ignoran restricciones, incentivos o información disponible.','Para uno mismo se invoca el contexto, pero para otra persona no.'],why:'La persona es más visible que las condiciones que la rodean; nuestras propias circunstancias, en cambio, son más accesibles.',counter:'Describe la situación desde el punto de vista de la otra persona. Pregunta qué restricciones o incentivos pudieron influir antes de inferir rasgos.',examples:['“Llegó tarde porque es irresponsable”, sin conocer una demora del transporte.','Atribuir un error de un colega a incompetencia sin revisar la carga de trabajo.','Explicar una decisión ajena por su personalidad, pero la propia por las circunstancias.'],cases:[{title:'Atribución de conducta y situación',text:'Ross describió el error fundamental de atribución como una tendencia a sobrevalorar disposiciones al explicar la conducta.',source:'Ross (1977)',url:'https://doi.org/10.1016/S0065-2601(08)60357-3'},{title:'Variación cultural en atribución',text:'Un metaanálisis documenta variación intercultural en la atribución disposicional y contextual.',source:'Miyamoto & Kitayama (2002)',url:'https://doi.org/10.1037/0033-2909.128.5.713'},{title:'Reevaluación de explicaciones disposicionales',text:'La literatura examina límites y reformulaciones del concepto en psicología social.',source:'Gawronski (2004)',url:'https://doi.org/10.1207/s15327957pspr0804_2'}],sources:[['Ross (1977)','https://doi.org/10.1016/S0065-2601(08)60357-3'],['Miyamoto & Kitayama (2002)','https://doi.org/10.1037/0033-2909.128.5.713'],['Gawronski (2004)','https://doi.org/10.1207/s15327957pspr0804_2']],videos:[['Fundamental Attribution Error — McCombs School of Business','https://www.youtube.com/watch?v=Y8IcYSrcaaA',0,'Explicación con ejemplos'],['Introduction to Cognitive Bias — Crash Course','https://www.youtube.com/watch?v=d2r7Bk1NlgU',0,'Introducción a sesgos'],['12 Cognitive Biases Explained','https://www.youtube.com/watch?v=m3Nfnp4NAdg',335,'Segmento Fundamental Attribution Error, 05:35']]},
 {id:'exceso-confianza',kind:'sesgo',name:'Exceso de confianza',category:'Estimación y decisión',short:'La confianza subjetiva supera la precisión real del juicio o la estimación.',description:'La confianza puede estar mal calibrada, en especial en tareas difíciles. No debe inferirse solo por un tono seguro: se compara confianza con aciertos en una serie de juicios.',signals:['Predicciones muy seguras sin rango ni tasa de aciertos.','Se ignoran márgenes de error.','No se revisa el historial de predicciones.'],why:'Las personas pueden subestimar incertidumbre y no considerar alternativas o límites de conocimiento.',counter:'Registra predicciones y confianza antes de conocer resultados. Usa rangos, tasas base y revisión retrospectiva.',examples:['Un pronóstico puntual se presenta sin intervalo de incertidumbre.','Alguien confía en que recuerda correctamente una cifra, pero no la comprueba.','Un equipo descarta escenarios alternativos sin evaluar probabilidades.'],cases:[{title:'Sobreconfianza en juicios probabilísticos',text:'Experimentos y revisiones documentan sobreconfianza como discrepancia entre confianza y precisión.',source:'Lichtenstein, Fischhoff & Phillips (1982)',url:'https://doi.org/10.1016/S0065-2601(08)60384-2'},{title:'Revisión de sobreconfianza',text:'Moore y Healy distinguen formas de exceso de confianza y sus causas.',source:'Moore & Healy (2008)',url:'https://doi.org/10.1037/0033-295X.115.2.502'},{title:'Calibración y conocimiento',text:'La investigación analiza el papel de pericia, dificultad y calibración en predicción.',source:'Klayman et al. (1999)',url:'https://doi.org/10.1037/0033-295X.106.1.67'}],sources:[['Lichtenstein, Fischhoff & Phillips (1982)','https://doi.org/10.1016/S0065-2601(08)60384-2'],['Moore & Healy (2008)','https://doi.org/10.1037/0033-295X.115.2.502'],['Klayman et al. (1999)','https://doi.org/10.1037/0033-295X.106.1.67']],videos:[['12 Cognitive Biases Explained','https://www.youtube.com/watch?v=wEwGBIr_RIw',0,'Sesgos y decisiones'],['Introduction to Cognitive Bias — Crash Course','https://www.youtube.com/watch?v=d2r7Bk1NlgU',0,'Introducción'],['Hidden Traps in Decision Making','https://www.youtube.com/watch?v=gkIkqJMdv2o',0,'Decisiones bajo sesgo']]},
 {id:'verdad-ilusoria',kind:'sesgo',name:'Efecto de verdad ilusoria',category:'Memoria y repetición',short:'La repetición puede hacer que una afirmación parezca más verdadera o familiar.',description:'La familiaridad derivada de repetir una afirmación puede aumentar su veracidad percibida, incluso cuando la verdad objetiva no cambia. No es una medida de la verdad de la afirmación.',signals:['La repetición se ofrece como prueba.','Una afirmación familiar se siente más plausible sin nueva evidencia.','Se confunde reconocimiento con verificación.'],why:'La repetición puede facilitar el procesamiento y esa facilidad puede confundirse con familiaridad o verdad.',counter:'Pregunta por evidencia independiente y fuentes primarias. Comprueba la afirmación como si la vieras por primera vez.',examples:['Un rumor repetido parece plausible aunque no aparezca evidencia nueva.','Un eslogan conocido se recuerda como hecho.','Una afirmación compartida muchas veces parece corroborada cuando todos la copiaron de la misma fuente.'],cases:[{title:'Repetición y verdad percibida',text:'Experimentos muestran que la exposición repetida puede aumentar la verdad percibida de afirmaciones.',source:'Hasher, Goldstein & Toppino (1977)',url:'https://doi.org/10.1016/S0022-5371(77)80012-1'},{title:'Persistencia del efecto por repetición',text:'Tres experimentos longitudinales investigaron la duración de la inoculación contra técnicas de desinformación; hallaron efectos que persistieron al menos tres meses en las condiciones estudiadas.',source:'Maertens et al. (2021)',url:'https://doi.org/10.1037/xap0000315'},{title:'Metaanálisis actualizado de verdad ilusoria',text:'Metaanálisis de estudios publicados hasta 2025 evalúa tamaño del efecto y moderadores.',source:'Systematic review & meta-analysis (2026)',url:'https://www.nature.com/articles/s41467-026-70041-x'}],sources:[['Hasher, Goldstein & Toppino (1977)','https://doi.org/10.1016/S0022-5371(77)80012-1'],['Maertens et al. (2021)','https://doi.org/10.1037/xap0000315'],['Systematic review & meta-analysis (2026)','https://www.nature.com/articles/s41467-026-70041-x']],videos:[['Introduction to Cognitive Bias — Crash Course','https://www.youtube.com/watch?v=d2r7Bk1NlgU',0,'Introducción a sesgos'],['12 Cognitive Biases Explained','https://www.youtube.com/watch?v=m3Nfnp4NAdg',317,'Segmento Illusory Truth Effect, 05:17'],['How to Trust Your Brain Online — Lisa Fazio','https://www.youtube.com/watch?v=NHjgKe7JMNE',0,'Repetición y credibilidad']]},
 {id:'ad-hominem',kind:'falacia',name:'Ad hominem',category:'Desvío y ataque',short:'Se ataca a la persona en vez de responder a la razón que presentó.',description:'Una crítica a la persona es falaz cuando se ofrece como sustituto de examinar el argumento. La credibilidad o los intereses de una fuente pueden ser pertinentes para valorar evidencia, pero no refutan automáticamente una conclusión.',signals:['Insultos o rasgos personales sustituyen la respuesta.','Se concluye que una afirmación es falsa por quién la dijo.','La conversación cambia del argumento a la biografía sin explicar su relevancia.'],why:'El ataque personal puede distraer de la pregunta central y activar respuestas emocionales o de grupo.',counter:'Separa la afirmación de quien la presenta. Pregunta qué evidencia respalda o refuta el argumento; evalúa la credibilidad solo cuando sea pertinente.',examples:['“Tu propuesta de transporte no vale porque ni siquiera sabes conducir”.','“No aceptes sus datos de presupuesto; es una persona desagradable”.','“Se equivoca sobre el horario porque ayer llegó tarde”.'],cases:[{title:'Falacias informales y discernimiento de noticias',text:'Ensayo experimental compara una intervención para aprender falacias informales con una intervención sobre noticias falsas.',source:'Learning about informal fallacies (2023)',url:'https://doi.org/10.1371/journal.pone.0283238'},{title:'Lógica informal y esquemas de argumentación',text:'La teoría de argumentación informal evalúa fallacias en contexto, no por palabras aisladas.',source:'Walton (1995)',url:'https://doi.org/10.1080/00048409512346401'},{title:'Purdue OWL: falacias lógicas',text:'Guía docente con definiciones y ejemplos habituales de falacias.',source:'Purdue Online Writing Lab',url:'https://owl.purdue.edu/owl/general_writing/academic_writing/logic_in_argumentative_writing/fallacies.html'}],sources:[['Learning about informal fallacies (2023)','https://doi.org/10.1371/journal.pone.0283238'],['Walton (1995)','https://doi.org/10.1080/00048409512346401'],['Purdue OWL: Fallacies','https://owl.purdue.edu/owl/general_writing/academic_writing/logic_in_argumentative_writing/fallacies.html']],videos:[['25 Common Logical Fallacies — Ad hominem','https://www.youtube.com/watch?v=floIILp9GNU',66,'Ejemplo identificado en el segmento Ad Hominem'],['10 Logical Fallacies That Destroy Conversations','https://www.youtube.com/watch?v=oHMVzfFY6X4',128,'Explicación de ad hominem'],['3 Hours of Most Common Logical Fallacies','https://www.youtube.com/watch?v=bNE4uBMsnP0',0,'Video panorámico con ejemplos']]},
 {id:'hombre-paja',kind:'falacia',name:'Hombre de paja',category:'Desvío y ataque',short:'Se distorsiona la postura ajena para refutar una versión más débil.',description:'La falacia ocurre cuando una respuesta sustituye la posición real por una versión exagerada o simplificada. Antes de señalarla, conviene comprobar que la posición original esté representada con fidelidad.',signals:['La réplica responde a una versión extrema que nadie defendió.','Se omiten matices centrales de la postura original.','La conclusión parece fácil porque cambió la afirmación debatida.'],why:'Una versión simplificada resulta más fácil de refutar y puede movilizar al público contra una posición ajena.',counter:'Parafrasea la postura contraria y pide confirmación. Responde a su versión más sólida antes de criticarla.',examples:['A: “Regulemos algunas emisiones”. B: “Quieres cerrar todas las fábricas”.','A: “Conviene limitar el uso del móvil en clase”. B: “Piensas que la tecnología es inútil”.','A: “Hace falta una reforma gradual”. B: “Propones cambiarlo todo de golpe”.'],cases:[{title:'Aprendizaje de falacias informales',text:'Intervención educativa enseña formas de argumentación falaz y evalúa transferencia a discernimiento de noticias.',source:'PLOS ONE (2023)',url:'https://doi.org/10.1371/journal.pone.0283238'},{title:'Falacias y discusión crítica',text:'La evaluación de un argumento informal requiere el contexto conversacional y la postura efectivamente planteada.',source:'Johnson & Blair (2006)',url:'https://doi.org/10.1080/00048400600782963'},{title:'Ejemplos audiovisuales para enseñanza',text:'Colección docente utiliza clips de anuncios y programas para analizar ejemplos de hombre de paja y otros razonamientos.',source:'Laura Randazzo: clips de falacias',url:'https://laurarandazzo.com/logical-fallacies-football-battle-royale-commercials/'}],sources:[['PLOS ONE (2023)','https://doi.org/10.1371/journal.pone.0283238'],['Johnson & Blair (2006)','https://doi.org/10.1080/00048400600782963'],['Laura Randazzo: Logical Fallacies clips','https://laurarandazzo.com/logical-fallacies-football-battle-royale-commercials/']],videos:[['25 Common Logical Fallacies — Strawman','https://www.youtube.com/watch?v=floIILp9GNU',105,'Ejemplo identificado en el segmento Strawman'],['10 Logical Fallacies That Destroy Conversations','https://www.youtube.com/watch?v=oHMVzfFY6X4',361,'Explicación de straw man'],['3 Hours of Most Common Logical Fallacies','https://www.youtube.com/watch?v=bNE4uBMsnP0',0,'Panorama educativo de falacias']]},
 {id:'falso-dilema',kind:'falacia',name:'Falso dilema',category:'Desvío y ataque',short:'Presenta dos opciones como las únicas posibles cuando hay más alternativas.',description:'Una disyuntiva no es falaz si las opciones son realmente exhaustivas. El error consiste en excluir alternativas relevantes sin justificarlo.',signals:['“O estás conmigo o estás contra mí”.','Se exige escoger entre dos caminos sin mostrar que agotan las posibilidades.','Se ocultan opciones intermedias o combinaciones.'],why:'Una elección binaria simplifica la discusión y puede presionar una decisión antes de explorar alternativas.',counter:'Enumera opciones adicionales. Pregunta si las alternativas son exhaustivas y qué evidencia excluye las demás.',examples:['“O aceptamos este plan hoy o la empresa fracasa”.','“Si te importa el ambiente, debes dejar de viajar por completo”.','“O estás de acuerdo con cada medida o no te importa el problema”.'],cases:[{title:'Falacias informales y discernimiento de noticias',text:'Estudio experimental sobre aprendizaje de falacias informales en materiales educativos.',source:'PLOS ONE (2023)',url:'https://doi.org/10.1371/journal.pone.0283238'},{title:'Guía de razonamiento lógico',text:'La guía docente describe razonamientos disyuntivos engañosos y ejemplos de falacias.',source:'Purdue OWL',url:'https://owl.purdue.edu/owl/general_writing/academic_writing/logic_in_argumentative_writing/fallacies.html'},{title:'Argumentación informal',text:'El estudio de argumentos requiere atender al contexto y a la carga de prueba.',source:'Walton (1995)',url:'https://doi.org/10.1080/00048409512346401'}],sources:[['PLOS ONE (2023)','https://doi.org/10.1371/journal.pone.0283238'],['Purdue OWL: Fallacies','https://owl.purdue.edu/owl/general_writing/academic_writing/logic_in_argumentative_writing/fallacies.html'],['Walton (1995)','https://doi.org/10.1080/00048409512346401']],videos:[['25 Common Logical Fallacies — False Dilemma','https://www.youtube.com/watch?v=floIILp9GNU',213,'Ejemplo identificado en False Dilemma'],['10 Logical Fallacies That Destroy Conversations','https://www.youtube.com/watch?v=oHMVzfFY6X4',791,'Explicación de falso dilema'],['3 Hours of Most Common Logical Fallacies','https://www.youtube.com/watch?v=bNE4uBMsnP0',0,'Panorama educativo']]},
 {id:'causa-falsa',kind:'falacia',name:'Falsa causa',category:'Causa y evidencia',short:'Concluye que un evento causó otro solo porque ocurrieron juntos o en secuencia.',description:'La coincidencia temporal o correlación no demuestra causalidad. Para sostener una causa se necesita evidencia y descartar explicaciones alternativas.',signals:['“Después de esto, por tanto a causa de esto”.','La correlación se presenta como prueba causal.','No se consideran variables de confusión ni mecanismo plausible.'],why:'Las personas buscan patrones y explicaciones; una secuencia temporal clara puede parecer suficiente para establecer causa.',counter:'Pregunta por grupo de comparación, orden temporal, mecanismo y variables alternativas. Consulta diseños que permitan inferencia causal.',examples:['“Me puse esta pulsera y luego aprobé; la pulsera me dio suerte”.','“Las ventas crecieron después del anuncio, así que el anuncio fue la única causa”.','“Dos variables subieron juntas, por eso una produjo la otra”.'],cases:[{title:'Correlación y causalidad en inferencia',text:'Pearl presenta herramientas causales para diferenciar asociación de relación causal.',source:'Pearl (1995)',url:'https://doi.org/10.1016/0004-3702(95)00057-I'},{title:'Diseños y explicaciones causales',text:'Una revisión explica el razonamiento causal y los límites de inferir causas desde asociaciones.',source:'Hernán & Robins (2020)',url:'https://www.hsph.harvard.edu/miguel-hernan/causal-inference-book/'},{title:'Falacias informales y evaluación',text:'En argumentos cotidianos, evaluar una causa requiere premisas y contexto, no solo forma lingüística.',source:'PLOS ONE (2023)',url:'https://doi.org/10.1371/journal.pone.0283238'}],sources:[['Pearl (1995)','https://doi.org/10.1016/0004-3702(95)00057-I'],['Hernán & Robins (2020)','https://www.hsph.harvard.edu/miguel-hernan/causal-inference-book/'],['PLOS ONE (2023)','https://doi.org/10.1371/journal.pone.0283238']],videos:[['25 Common Logical Fallacies — Post Hoc','https://www.youtube.com/watch?v=floIILp9GNU',501,'Segmento Post Hoc / causalidad'],['25 Common Logical Fallacies — False Cause','https://www.youtube.com/watch?v=44XeNCfHpLw',0,'Introducción a falacias con ejemplos'],['3 Hours of Most Common Logical Fallacies','https://www.youtube.com/watch?v=bNE4uBMsnP0',0,'Panorama educativo']]},
 {id:'generalizacion',kind:'falacia',name:'Generalización apresurada',category:'Causa y evidencia',short:'Generaliza a partir de una muestra pequeña, sesgada o poco representativa.',description:'Una muestra limitada puede no respaldar una afirmación sobre una población entera. El tamaño no es el único criterio: importan selección, medición y representatividad.',signals:['Conclusión universal desde una anécdota.','No se conoce cómo se seleccionaron los casos.','Se confunde muestra conveniente con población general.'],why:'Los ejemplos vívidos pueden parecer informativos, aunque no representen la variedad de casos.',counter:'Pregunta cuántos casos, cómo se eligieron y qué población representan. Busca datos con muestreo adecuado y límites explícitos.',examples:['“Dos clientes se quejaron; a nadie le gusta el servicio”.','“Conocí a una persona de esa ciudad que fue grosera; todos son así”.','“A tres estudiantes les funcionó este método; funciona para cualquiera”.'],cases:[{title:'Muestras pequeñas y generalización',text:'La inferencia a una población requiere justificar selección y representatividad de la muestra.',source:'Cochran (1977)',url:'https://doi.org/10.1002/9781118162934'},{title:'Muestreo y evidencia',text:'Un texto metodológico explica cómo diseños de muestreo afectan las inferencias poblacionales.',source:'Kish (1965)',url:'https://doi.org/10.1002/9781118548196'},{title:'Falacias y noticias',text:'Investigación experimental considera inferencias informales en mensajes de noticias.',source:'PLOS ONE (2023)',url:'https://doi.org/10.1371/journal.pone.0283238'}],sources:[['Cochran (1977)','https://doi.org/10.1002/9781118162934'],['Kish (1965)','https://doi.org/10.1002/9781118548196'],['PLOS ONE (2023)','https://doi.org/10.1371/journal.pone.0283238']],videos:[['25 Common Logical Fallacies — Hasty Generalization','https://www.youtube.com/watch?v=floIILp9GNU',359,'Segmento Hasty Generalization'],['Rich Men vs Poor Men — example analysis','https://youtu.be/_GAELbt-VXE?t=2055',2055,'Example of an overgeneralized claim; context matters'],['3 Hours of Most Common Logical Fallacies','https://www.youtube.com/watch?v=bNE4uBMsnP0',0,'Panorama educativo']]},
 {id:'autoridad',kind:'falacia',name:'Apelación indebida a la autoridad',category:'Causa y evidencia',short:'Usa el prestigio de una autoridad como sustituto de evidencia pertinente.',description:'La experiencia puede ser evidencia relevante cuando es especializada, pertinente y bien atribuida. La apelación es débil cuando una celebridad o autoridad en otro campo reemplaza datos o consenso experto.',signals:['Una persona famosa o prestigiosa se usa como única prueba.','La especialidad no coincide con el tema.','No se informa qué evidencia respalda la opinión experta.'],why:'El prestigio puede funcionar como atajo cuando evaluar la evidencia requiere conocimientos o tiempo.',counter:'Verifica especialidad, consenso y evidencia citada. Distingue opinión experta informada de prueba concluyente.',examples:['“Este actor recomienda el suplemento, así que debe funcionar”.','“Un científico de otra disciplina apoyó la política, por lo tanto está probada”.','“La marca lo anuncia como recomendado por especialistas, pero no identifica estudios”.'],cases:[{title:'Autoridad y argumentación',text:'El análisis de argumentos de autoridad distingue la apelación razonable de la falaz según credenciales, campo y evidencia.',source:'Walton (1997)',url:'https://doi.org/10.1080/02691729708578842'},{title:'Comunicación de la ciencia y expertos',text:'Estudio sobre confianza y comunicación científica examina cómo públicos valoran fuentes expertas.',source:'National Academies (2016)',url:'https://doi.org/10.17226/23674'},{title:'Falacias en discernimiento de noticias',text:'Intervención experimental trata aprendizaje de falacias informales con materiales informativos.',source:'PLOS ONE (2023)',url:'https://doi.org/10.1371/journal.pone.0283238'}],sources:[['Walton (1997)','https://doi.org/10.1080/02691729708578842'],['National Academies (2016)','https://doi.org/10.17226/23674'],['PLOS ONE (2023)','https://doi.org/10.1371/journal.pone.0283238']],videos:[['25 Common Logical Fallacies — Appeal to Authority','https://www.youtube.com/watch?v=floIILp9GNU',431,'Segmento Appeal to Authority'],['10 Logical Fallacies That Destroy Conversations','https://www.youtube.com/watch?v=oHMVzfFY6X4',0,'Panorama de falacias'],['3 Hours of Most Common Logical Fallacies','https://www.youtube.com/watch?v=bNE4uBMsnP0',0,'Video educativo']]},
 {id:'ignorancia',kind:'falacia',name:'Apelación a la ignorancia',category:'Causa y evidencia',short:'Toma la falta de prueba a favor como prueba en contra, o al revés.',description:'La ausencia de evidencia puede ser informativa si se esperaba encontrarla con un método capaz de detectarla. No equivale automáticamente a evidencia de falsedad ni de verdad.',signals:['“No se ha demostrado falso, así que es verdad”.','“No hay prueba concluyente, así que es imposible”.','Se omite si la búsqueda habría detectado la evidencia.'],why:'La incertidumbre puede confundirse con una respuesta definitiva, especialmente cuando se exige resolver una cuestión.',counter:'Aclara qué sabemos, qué no, y qué probabilidad de detectar evidencia tenía el método usado. No conviertas desconocimiento en certeza.',examples:['“Nadie probó que no existan, por eso los fantasmas existen”.','“No encontramos el archivo, entonces nunca existió”.','“No hay estudios sobre ese efecto, por lo tanto no existe”.'],cases:[{title:'Evidencia negativa y confirmación',text:'La lógica de prueba y falsación requiere distinguir ausencia de evidencia de evidencia de ausencia según sensibilidad del método.',source:'Popper (1959)',url:'https://doi.org/10.4324/9780203538074'},{title:'Falacias informales',text:'Estudio educativo evalúa aprendizaje de falacias, incluyendo formas de razonamiento basadas en ignorancia.',source:'PLOS ONE (2023)',url:'https://doi.org/10.1371/journal.pone.0283238'},{title:'Razonamiento argumentativo',text:'El análisis de argumentos por ignorancia depende de cargas de prueba y condiciones contextuales.',source:'Walton (1996)',url:'https://doi.org/10.1007/978-94-015-8713-1'}],sources:[['Popper (1959)','https://doi.org/10.4324/9780203538074'],['PLOS ONE (2023)','https://doi.org/10.1371/journal.pone.0283238'],['Walton (1996)','https://doi.org/10.1007/978-94-015-8713-1']],videos:[['25 Common Logical Fallacies — Appeal to Ignorance','https://www.youtube.com/watch?v=floIILp9GNU',165,'Segmento Appeal to Ignorance'],['10 Logical Fallacies That Destroy Conversations','https://www.youtube.com/watch?v=oHMVzfFY6X4',0,'Panorama de falacias'],['3 Hours of Most Common Logical Fallacies','https://www.youtube.com/watch?v=bNE4uBMsnP0',0,'Video educativo']]},
 {id:'pendiente-resbaladiza',kind:'falacia',name:'Pendiente resbaladiza',category:'Causa y evidencia',short:'Asegura que un primer paso conducirá inevitablemente a una cadena de consecuencias extremas.',description:'Una cadena de consecuencias puede ser plausible si hay mecanismos y evidencia para cada eslabón. La falacia consiste en asumir la inevitabilidad sin justificar la secuencia.',signals:['Se pronostica una cadena dramática sin explicar los pasos.','Se trata un riesgo como resultado seguro.','No se consideran frenos o alternativas entre etapas.'],why:'Las narrativas de cadena hacen visibles posibles consecuencias y pueden generar urgencia, aunque omitan probabilidades.',counter:'Pide evidencia para cada eslabón y estima probabilidad condicional. Busca puntos donde la secuencia podría interrumpirse.',examples:['“Si permitimos una extensión de plazo, nadie entregará nada a tiempo”.','“Si se regula un producto, pronto se prohibirán todos”.','“Si aceptas una excepción, desaparecerán todas las reglas”.'],cases:[{title:'Argumentación sobre cadenas causales',text:'La literatura de lógica informal analiza cuándo argumentos de pendiente resbaladiza son aceptables o falaces.',source:'Walton (1992)',url:'https://doi.org/10.1016/0010-0277(92)90022-S'},{title:'Evaluación de riesgos',text:'La inferencia de riesgos requiere explicitar probabilidad, secuencia causal y evidencia para cada paso.',source:'National Research Council (1983)',url:'https://doi.org/10.17226/776'},{title:'Falacias informales en aprendizaje',text:'Estudio experimental incorpora falacias de argumentación informal en una intervención didáctica.',source:'PLOS ONE (2023)',url:'https://doi.org/10.1371/journal.pone.0283238'}],sources:[['Walton (1992)','https://doi.org/10.1016/0010-0277(92)90022-S'],['National Research Council (1983)','https://doi.org/10.17226/776'],['PLOS ONE (2023)','https://doi.org/10.1371/journal.pone.0283238']],videos:[['25 Common Logical Fallacies — Slippery Slope','https://www.youtube.com/watch?v=floIILp9GNU',266,'Segmento Slippery Slope'],['10 Logical Fallacies That Destroy Conversations','https://www.youtube.com/watch?v=oHMVzfFY6X4',0,'Panorama con ejemplos'],['3 Hours of Most Common Logical Fallacies','https://www.youtube.com/watch?v=bNE4uBMsnP0',0,'Video educativo']]},
 {id:'circular',kind:'falacia',name:'Razonamiento circular',category:'Causa y evidencia',short:'La conclusión se repite como premisa sin aportar una justificación independiente.',description:'La premisa presupone la conclusión que intenta establecer. A veces el círculo queda oculto en una paráfrasis o en varias premisas que dependen unas de otras.',signals:['La conclusión aparece reformulada como razón.','Una premisa solo se acepta si ya se cree la conclusión.','No hay evidencia independiente que apoye el punto central.'],why:'La repetición puede dar sensación de explicación aunque el argumento no avance.',counter:'Escribe las premisas y la conclusión por separado. Pregunta qué apoya cada premisa sin recurrir a la conclusión.',examples:['“Este medio es confiable porque publica información verdadera; sabemos que es verdadera porque la publica este medio”.','“La regla es justa porque es correcta; es correcta porque así lo indica la regla”.','“El producto es el mejor porque es superior a los demás”.'],cases:[{title:'Falacias y suficiencia de apoyo',text:'El análisis de falacias informales aborda argumentos cuyas premisas no justifican adecuadamente la conclusión.',source:'PLOS ONE (2023)',url:'https://doi.org/10.1371/journal.pone.0283238'},{title:'Argumentación circular',text:'Guía de lógica identifica razonamiento circular como argumento que presupone lo que intenta probar.',source:'Purdue OWL',url:'https://owl.purdue.edu/owl/general_writing/academic_writing/logic_in_argumentative_writing/fallacies.html'},{title:'Lógica informal',text:'Estudio de argumentación crítica enfatiza la evaluación contextual del apoyo de las premisas.',source:'Johnson & Blair (2006)',url:'https://doi.org/10.1080/00048400600782963'}],sources:[['PLOS ONE (2023)','https://doi.org/10.1371/journal.pone.0283238'],['Purdue OWL: Fallacies','https://owl.purdue.edu/owl/general_writing/academic_writing/logic_in_argumentative_writing/fallacies.html'],['Johnson & Blair (2006)','https://doi.org/10.1080/00048400600782963']],videos:[['25 Common Logical Fallacies — Circular Reasoning','https://www.youtube.com/watch?v=floIILp9GNU',317,'Segmento Circular Reasoning'],['3 Hours of Most Common Logical Fallacies','https://www.youtube.com/watch?v=bNE4uBMsnP0',0,'Video panorámico'],['Logical Fallacies (2026)','https://www.youtube.com/watch?v=44XeNCfHpLw',0,'Introducción a falacias']]},
 {id:'red-herring',kind:'falacia',name:'Pista falsa (red herring)',category:'Desvío y ataque',short:'Desvía la conversación hacia un tema que no responde la cuestión central.',description:'Un dato puede ser verdadero y aun así resultar irrelevante para la conclusión discutida. El desvío es falaz cuando evita la carga argumentativa en lugar de aportar una razón pertinente.',signals:['La respuesta cambia de tema ante una pregunta directa.','El asunto alternativo no afecta la conclusión original.','La conversación se centra en una polémica lateral.'],why:'Los temas emocionalmente atractivos pueden captar la atención y desplazar una cuestión difícil.',counter:'Reformula la pregunta original y explica por qué la respuesta no la aborda. Si el tema alternativo importa, vuelve a él después.',examples:['Preguntan por el costo de un programa y se responde que el equipo trabaja mucho.','Una crítica a una política se contesta con un dato irrelevante sobre el crítico.','Se debate el rendimiento de una herramienta y se cambia a la popularidad de su marca.'],cases:[{title:'Desvíos y falacias en argumentación',text:'La evaluación de falacias informales exige analizar pertinencia de premisas y movimientos discursivos.',source:'PLOS ONE (2023)',url:'https://doi.org/10.1371/journal.pone.0283238'},{title:'Normas de discusión crítica',text:'La pragmadialéctica examina reglas de discusión y movimientos que obstaculizan resolver desacuerdos.',source:'van Eemeren & Grootendorst (2004)',url:'https://doi.org/10.1017/CBO9780511616389'},{title:'Falacias argumentativas',text:'Guía docente resume desvíos irrelevantes y otros errores argumentativos frecuentes.',source:'Purdue OWL',url:'https://owl.purdue.edu/owl/general_writing/academic_writing/logic_in_argumentative_writing/fallacies.html'}],sources:[['PLOS ONE (2023)','https://doi.org/10.1371/journal.pone.0283238'],['van Eemeren & Grootendorst (2004)','https://doi.org/10.1017/CBO9780511616389'],['Purdue OWL: Fallacies','https://owl.purdue.edu/owl/general_writing/academic_writing/logic_in_argumentative_writing/fallacies.html']],videos:[['25 Common Logical Fallacies — Red Herring','https://www.youtube.com/watch?v=floIILp9GNU',393,'Segmento Red Herring'],['3 Hours of Most Common Logical Fallacies','https://www.youtube.com/watch?v=bNE4uBMsnP0',0,'Video panorámico'],['10 Logical Fallacies That Destroy Conversations','https://www.youtube.com/watch?v=oHMVzfFY6X4',0,'Explicación de falacias']]},
 {id:'tu-quoque',kind:'falacia',name:'Tu quoque (y tú también)',category:'Desvío y ataque',short:'Rechaza una crítica señalando que quien la hace también actúa de forma incoherente.',description:'La inconsistencia de una persona puede ser relevante para evaluar su coherencia o credibilidad, pero no demuestra por sí sola que la crítica sea falsa.',signals:['“Tú también lo haces” reemplaza responder al punto.','La conducta del crítico se usa como refutación automática.','No se evalúa la evidencia de la afirmación original.'],why:'La acusación de hipocresía convierte la discusión en una evaluación de personas y puede aliviar la presión de responder.',counter:'Reconoce si la crítica es válida aunque quien la diga no la cumpla. Después discute por separado la coherencia del mensajero.',examples:['“No puedes pedirme que recicle porque tú no siempre reciclas”.','“No escuches su consejo de ahorro: una vez compró algo caro”.','“Tu crítica a la puntualidad no cuenta porque llegaste tarde ayer”.'],cases:[{title:'Tu quoque y ataques personales',text:'Análisis de la falacia ad hominem distingue refutación de una tesis y crítica al interlocutor.',source:'Walton (1998)',url:'https://doi.org/10.1007/978-94-011-5442-5'},{title:'Falacias informales en enseñanza',text:'Estudio experimental evalúa contenidos sobre falacias y discernimiento de noticias.',source:'PLOS ONE (2023)',url:'https://doi.org/10.1371/journal.pone.0283238'},{title:'Argumentación y relevancia',text:'Las reglas de discusión crítica ayudan a separar argumentos sobre la tesis y ataques al hablante.',source:'van Eemeren & Grootendorst (2004)',url:'https://doi.org/10.1017/CBO9780511616389'}],sources:[['Walton (1998)','https://doi.org/10.1007/978-94-011-5442-5'],['PLOS ONE (2023)','https://doi.org/10.1371/journal.pone.0283238'],['van Eemeren & Grootendorst (2004)','https://doi.org/10.1017/CBO9780511616389']],videos:[['25 Common Logical Fallacies — Tu Quoque','https://www.youtube.com/watch?v=floIILp9GNU',601,'Segmento Tu Quoque'],['25 Common Logical Fallacies — Ad Hominem','https://www.youtube.com/watch?v=floIILp9GNU',66,'Ejemplo afín de ataque personal'],['3 Hours of Most Common Logical Fallacies','https://www.youtube.com/watch?v=bNE4uBMsnP0',0,'Panorama de falacias']]},
 {id:'popularidad',kind:'falacia',name:'Apelación a la popularidad',category:'Desvío y ataque',short:'Concluye que una idea es verdadera o buena porque muchas personas la creen o la eligen.',description:'La popularidad puede ser evidencia pertinente de preferencias o difusión, no necesariamente de verdad, eficacia o calidad. La falacia aparece cuando el número de adherentes sustituye evidencia para otra conclusión.',signals:['“Todo el mundo lo hace” se ofrece como prueba de verdad.','Seguidores o ventas sustituyen criterios de calidad.','La mayoría se presenta como infalible.'],why:'La aprobación social sirve como señal rápida cuando no hay información suficiente, pero puede confundir consenso con prueba.',counter:'Aclara qué demuestra la popularidad y qué no. Busca evidencia independiente sobre la afirmación específica.',examples:['“Millones lo compraron; por eso cura”.','“La mayoría en redes dice que ocurrió, así que sucedió”.','“Es la mejor escuela porque es la más conocida”.'],cases:[{title:'Popularidad como señal y verdad',text:'La psicología de juicios sociales distingue información social útil de inferencias que extrapolan indebidamente al contenido.',source:'Asch (1955)',url:'https://doi.org/10.1037/h0046408'},{title:'Repetición, familiaridad y creencia',text:'Metaanálisis reciente evalúa cómo la repetición afecta la verdad percibida; popularidad y veracidad no son equivalentes.',source:'Nature Communications (2026)',url:'https://www.nature.com/articles/s41467-026-70041-x'},{title:'Falacias informales',text:'Estudio de intervención trabaja reconocimiento de razonamientos falaces en mensajes informativos.',source:'PLOS ONE (2023)',url:'https://doi.org/10.1371/journal.pone.0283238'}],sources:[['Asch (1955)','https://doi.org/10.1037/h0046408'],['Nature Communications (2026)','https://www.nature.com/articles/s41467-026-70041-x'],['PLOS ONE (2023)','https://doi.org/10.1371/journal.pone.0283238']],videos:[['25 Common Logical Fallacies — Bandwagon','https://www.youtube.com/watch?v=floIILp9GNU',474,'Segmento Bandwagon'],['3 Hours of Most Common Logical Fallacies','https://www.youtube.com/watch?v=bNE4uBMsnP0',0,'Video educativo'],['10 Logical Fallacies That Destroy Conversations','https://www.youtube.com/watch?v=oHMVzfFY6X4',0,'Panorama de falacias']]},
 {id:'emocion',kind:'falacia',name:'Apelación a la emoción',category:'Desvío y ataque',short:'Usa una emoción como sustituto de evidencia pertinente para la conclusión.',description:'Las emociones pueden ser relevantes en deliberaciones morales o decisiones personales. El error ocurre cuando miedo, lástima, orgullo o indignación reemplazan el apoyo necesario para una afirmación factual o inferencial.',signals:['Se exige aceptar una conclusión porque provoca miedo o compasión.','El impacto emocional sustituye hechos y razones.','Quien duda es presentado como cruel o insensible.'],why:'Las emociones guían atención y valoración, pero pueden empujar a conclusiones antes de examinar evidencia.',counter:'Reconoce la emoción y luego separa qué afirma el mensaje, qué pruebas ofrece y qué información falta.',examples:['“Aprueba esta propuesta o serás responsable de todo lo malo que ocurra”.','Una historia conmovedora se usa como única prueba de que una política siempre funciona.','“Si te importan los niños, debes aceptar esta cifra sin preguntar”.'],cases:[{title:'Emoción moral y circulación de mensajes',text:'Estudio observacional encontró asociaciones entre palabras morales-emocionales y difusión en redes; no prueba que toda apelación emocional sea falaz.',source:'Brady et al. (2017)',url:'https://doi.org/10.1073/pnas.1618923114'},{title:'Emoción en razonamiento',text:'La investigación revisa cómo la emoción influye en juicio y toma de decisiones.',source:'Lerner et al. (2015)',url:'https://doi.org/10.1146/annurev-psych-010213-115043'},{title:'Falacias informales y noticias',text:'Estudio experimental analiza enseñanza de falacias en materiales sobre información falsa.',source:'PLOS ONE (2023)',url:'https://doi.org/10.1371/journal.pone.0283238'}],sources:[['Brady et al. (2017)','https://doi.org/10.1073/pnas.1618923114'],['Lerner et al. (2015)','https://doi.org/10.1146/annurev-psych-010213-115043'],['PLOS ONE (2023)','https://doi.org/10.1371/journal.pone.0283238']],videos:[['25 Common Logical Fallacies — Appeal to Emotion','https://www.youtube.com/watch?v=floIILp9GNU',540,'Segmento Appeal to Emotion'],['10 Logical Fallacies That Destroy Conversations','https://www.youtube.com/watch?v=oHMVzfFY6X4',0,'Panorama de ejemplos'],['3 Hours of Most Common Logical Fallacies','https://www.youtube.com/watch?v=bNE4uBMsnP0',0,'Video educativo']]},
 {id:'falsa-analogia',kind:'falacia',name:'Falsa analogía',category:'Desvío y ataque',short:'Compara dos casos que comparten rasgos, pero difieren en aspectos relevantes para la conclusión.',description:'Las analogías ayudan a razonar si las similitudes pertinentes superan las diferencias relevantes. No basta con encontrar cualquier parecido.',signals:['La comparación omite diferencias que afectan la conclusión.','Se transfiere una propiedad entre casos muy distintos.','La semejanza superficial hace todo el trabajo argumentativo.'],why:'Una comparación familiar puede hacer comprensible una idea nueva y ocultar límites de la correspondencia.',counter:'Enumera similitudes y diferencias relevantes. Pregunta si la propiedad inferida depende de los rasgos que ambos casos comparten.',examples:['“Una empresa es como una familia, así que los empleados deben obedecer sin preguntar”.','“El cerebro es una computadora; por lo tanto, olvidar equivale a borrar un archivo”.','“Este medicamento funcionó en un caso, así que será igual para todos”.'],cases:[{title:'Analogía y razonamiento',text:'La literatura de razonamiento analógico analiza transferencia de relaciones y límites de similitud.',source:'Gentner (1983)',url:'https://doi.org/10.1037/0033-295X.90.2.155'},{title:'Analogías en ciencia',text:'La investigación revisa cómo analogías contribuyen al razonamiento científico y cuándo pueden inducir a error.',source:'Dunbar & Blanchette (2001)',url:'https://doi.org/10.1016/S1364-6613(00)01661-3'},{title:'Falacias argumentales',text:'Intervención didáctica sobre falacias incluye ejemplos informales basados en argumentos cotidianos.',source:'PLOS ONE (2023)',url:'https://doi.org/10.1371/journal.pone.0283238'}],sources:[['Gentner (1983)','https://doi.org/10.1037/0033-295X.90.2.155'],['Dunbar & Blanchette (2001)','https://doi.org/10.1016/S1364-6613(00)01661-3'],['PLOS ONE (2023)','https://doi.org/10.1371/journal.pone.0283238']],videos:[['25 Common Logical Fallacies — False Analogy','https://www.youtube.com/watch?v=floIILp9GNU',570,'Segmento False Analogy'],['25 Common Logical Fallacies — Composition','https://www.youtube.com/watch?v=floIILp9GNU',732,'Ejemplo relacionado de transferencia entre partes y conjunto'],['3 Hours of Most Common Logical Fallacies','https://www.youtube.com/watch?v=bNE4uBMsnP0',0,'Video educativo']]},
 {id:'carga-prueba',kind:'falacia',name:'Traslado de la carga de la prueba',category:'Desvío y ataque',short:'Quien afirma algo exige que otros lo refuten en vez de aportar respaldo.',description:'La obligación de justificar una afirmación depende del contexto y de lo ya establecido. No toda petición de evidencia es una falacia; lo es usar la falta de refutación como respaldo propio.',signals:['“Demuéstrame que es falso” como único apoyo.','La afirmación extraordinaria no trae evidencia y exige refutación completa.','Se trata el silencio o la incertidumbre como confirmación.'],why:'Probar una negación amplia puede ser difícil, lo que permite que una afirmación sin apoyo parezca plausible.',counter:'Pide evidencia positiva y define qué observación apoyaría la afirmación. Considera quién está en posición de aportar esa evidencia.',examples:['“El objeto invisible está aquí; prueba que no”.','“Mi método cura, salvo que puedas demostrar lo contrario”.','“Nadie ha probado que esta predicción sea falsa, así que se cumplirá”.'],cases:[{title:'Argumentación y cargas de prueba',text:'El estudio de falacias y diálogo explica cómo se distribuye la obligación de sostener afirmaciones.',source:'Walton (1996)',url:'https://doi.org/10.1007/978-94-015-8713-1'},{title:'Falacias informales en educación',text:'Intervención experimental sobre aprendizaje de falacias y evaluación de noticias.',source:'PLOS ONE (2023)',url:'https://doi.org/10.1371/journal.pone.0283238'},{title:'Discusión crítica',text:'Las reglas de discusión argumentativa permiten reconocer tácticas que evaden obligaciones de sustento.',source:'van Eemeren & Grootendorst (2004)',url:'https://doi.org/10.1017/CBO9780511616389'}],sources:[['Walton (1996)','https://doi.org/10.1007/978-94-015-8713-1'],['PLOS ONE (2023)','https://doi.org/10.1371/journal.pone.0283238'],['van Eemeren & Grootendorst (2004)','https://doi.org/10.1017/CBO9780511616389']],videos:[['25 Common Logical Fallacies — Burden of Evidence','https://www.youtube.com/watch?v=floIILp9GNU',666,'Segmento Burden of Evidence'],['25 Common Logical Fallacies — Appeal to Ignorance','https://www.youtube.com/watch?v=floIILp9GNU',151,'Ejemplo relacionado de ausencia de prueba'],['3 Hours of Most Common Logical Fallacies','https://www.youtube.com/watch?v=bNE4uBMsnP0',0,'Video educativo']]}
].filter(c => !['exceso-confianza','tu-quoque','red-herring','emocion','falsa-analogia','carga-prueba'].includes(c.id));
